from decimal import Decimal
from typing import Any


def _text(value: Any) -> str:
    """Return the VRL string representation for text operations."""
    if value is None:
        return ""
    return str(value)


def _number(value: Any) -> Decimal:
    """Apply VRL numeric coercion, where empty values compare as zero."""
    if value is None or value == "":
        return Decimal("0")
    return Decimal(str(value))


def _nvl(value: Any, default: Any) -> Any:
    """Implement VRL NVL, treating missing, empty, and None as null."""
    if value is None or value == "":
        return default
    return value


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    today: str = "20260901",
) -> list[dict]:
    errors: list[dict] = []

    def fail(code: str, message: str, severity: str = "BLOCK") -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": severity,
            }
        )

    # ACC-001: rule-file order preserved.
    if event in ("INSERT", "UPDATE"):
        if len(_text(record.get("ACCT_NM", ""))) < 2:
            fail("E1001", "Account name too short")

    # ACC-002
    if event in ("INSERT", "UPDATE"):
        if _text(record.get("ACCT_TYP", "")) not in ("C", "P", "R", "X"):
            fail("E1002", "Invalid account type")

    # ACC-003
    if event in ("INSERT", "UPDATE"):
        annual_revenue = _nvl(record.get("ANN_REV", ""), 0)
        if _number(annual_revenue) < Decimal("0"):
            fail("E1003", "Annual revenue negative")

    # ACC-004
    if event == "UPDATE":
        prior = old if old is not None else {}
        releasing_hold_with_zero_limit = (
            _text(prior.get("CRED_HOLD", "")) == "Y"
            and _text(record.get("CRED_HOLD", "")) == "N"
            and _number(record.get("CRED_LIMIT", "")) <= Decimal("0")
        )
        if releasing_hold_with_zero_limit:
            fail("E1004", "Cannot release credit hold with zero credit limit")

    # ACC-005
    if event in ("INSERT", "UPDATE"):
        if len(_text(record.get("REGION_CD", ""))) != 3:
            fail("E1005", "Region code must be 3 chars", "WARN")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    return any(error.get("severity") == "BLOCK" for error in errors)
